edits.after:
static inline bool addr4_match(__be32 a1, __be32 a2, u8 prefixlen)
{
	/* C99 6.5.7 (3): u32 << 32 is undefined behaviour */
	if (sizeof(long) == 4 && prefixlen == 0)
		return true;
	if (prefixlen > 32)
		return false;
	return !((a1 ^ a2) & htonl(~0UL << (32 - prefixlen)));
}

